#!/usr/bin/env python3
# Source SHA-256: dc02049bec60fdf592b0500c761dc9d951672c0709cb5e4cd5e916d9f5f34265
import base64, hashlib, zlib
payload = ""
source = zlib.decompress(base64.b64decode(payload)).decode("utf-8")
actual = hashlib.sha256(source.encode("utf-8")).hexdigest()
if actual != "dc02049bec60fdf592b0500c761dc9d951672c0709cb5e4cd5e916d9f5f34265":
    raise SystemExit(f"RAR overlay: SHA256 mismatch: {actual}")
exec(compile(source, __file__, "exec"))
